namespace MassiveArmy.Industrial {
    [Serializable] public sealed class IndustrialDepositProjection {public int layoutVersion;public long id;public FramePose pose;}
    [Serializable] public sealed class IndustrialActorCheckpoint {public long id;public FramePose pose;public double health;public double collisionRadius=.35;public FramePose vehicleObstacle;public double vehicleObstacleRadius;}
    [Serializable] public sealed class IndustrialJournalEntry {
        public SurvivalWeaponAttack weaponAttack;public SurvivalRegistration registration;public SurvivalUniverseState universe;
        public long networkActor,networkSequence;public bool survivalCheckpoint;public SurvivalSessionState survival;public TribeCombatDamage playerCombat;public List<InventoryDropPosition> dropPositions;public InventoryTransaction inventory;public RespawnTransaction respawn;public long serial,actor,allocatedId,vehicleId;public FramePose vehiclePose;public FramePose actorPose;public IndustrialCommand command;public int steps,buildBody,stoneCost;public string buildJson,constructionItem;public int constructionCount;public double constructionActivity;public List<IndustrialConstructionSource> constructionSources;public bool constructionRefund,typedConstruction,kitRules,resourceRules,resourcePayment;public List<ItemStack> constructionPayment;public List<IndustrialMount> mounts;public List<IndustrialActorCheckpoint> actors;public List<IndustrialPowerEnvironment> powerEnvironments;public List<IndustrialHaulObstacle> haulObstacles;public bool logisticsRules;public List<IndustrialModulePorts> logisticsPorts;public bool miningWorkflowEnabled;public IndustrialWasteSite wasteSite;public IndustrialHaulReplan haulReplan;public List<IndustrialDepositProjection> depositProjections;
    }
    /// <summary>One authoritative writer. A flushed journal entry precedes each mutation.</summary>
    public sealed partial class IndustrialAuthority:IDisposable {
        public IndustrialWorld World {get;private set;}
        public Action<double,double> JournalTiming;public Action<double> CheckpointTiming;
        readonly object gate=new object();readonly string path;FileStream journal;StreamWriter writer;bool disposed;
        static readonly XmlSerializer worldSerializer=new XmlSerializer(typeof(IndustrialWorld));
        static readonly XmlSerializer entrySerializer=new XmlSerializer(typeof(IndustrialJournalEntry));
        public IndustrialAuthority(IndustrialWorld world,string savePath=null){
            World=world??throw new ArgumentNullException(nameof(world));path=savePath;
            if(path!=null){Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(path)));journal=new FileStream(path+".journal",FileMode.OpenOrCreate,FileAccess.Write,FileShare.Read);journal.Seek(0,SeekOrigin.End);writer=new StreamWriter(journal,new UTF8Encoding(false));}
        }
        static double PersistenceMilliseconds(long started)=>(System.Diagnostics.Stopwatch.GetTimestamp()-started)*1000.0/System.Diagnostics.Stopwatch.Frequency;
        void Append(IndustrialJournalEntry entry){
            entry.networkActor=networkActor;entry.networkSequence=networkSequence;entry.serial=World.journalSequence+1;
            if(writer!=null){
                long started=JournalTiming==null?0:System.Diagnostics.Stopwatch.GetTimestamp();double serialization=0;
                using(var text=new StringWriter(System.Globalization.CultureInfo.InvariantCulture)){
                    entrySerializer.Serialize(text,entry);byte[] data=Encoding.UTF8.GetBytes(text.ToString());writer.WriteLine(Convert.ToBase64String(data));
                    if(JournalTiming!=null){serialization=PersistenceMilliseconds(started);started=System.Diagnostics.Stopwatch.GetTimestamp();}
                    writer.Flush();journal.Flush(true);
                }
                if(JournalTiming!=null)try{JournalTiming(serialization,PersistenceMilliseconds(started));}catch(Exception){/* Diagnostics cannot reject a durable transaction. */}
            }
            World.journalSequence=entry.serial;if(networkSequence>0){var player=World.multiplayer?.players.Find(p=>p.actor==networkActor);if(player!=null)player.lastActionSequence=networkSequence;}
        }
        public CommandResult Execute(long actor,IndustrialCommand command){lock(gate){var who=World.Actor(actor);if(who==null)return new CommandResult(false,"Unknown actor");return World.Execute(actor,command,()=>Append(new IndustrialJournalEntry{resourceRules=true,kitRules=true,actor=actor,actorPose=who.pose,command=command}));}}
        // Called only after authoritative placement validation, never accepted as a raw wire command.
        public void CommitConstruction(long actor,int body,string json,int stoneCost){lock(gate){if(World.ConstructionPolicyError(actor)!=null)throw new InvalidOperationException(World.ConstructionPolicyError(actor));var a=World.Actor(actor);if(a==null||stoneCost>0&&a.inventory.Count("stone")<stoneCost||stoneCost<0&&!a.inventory.CanAdd("stone",-stoneCost))throw new InvalidOperationException("Construction payment unavailable");Append(new IndustrialJournalEntry{actor=actor,buildBody=body,buildJson=json,stoneCost=stoneCost,allocatedId=World.nextId});ApplyConstruction(World,actor,body,json,stoneCost);}}
        public void CommitConstructionItem(long actor,int body,string json,string item,int count,bool refund,List<IndustrialMount> mounts,double activity=0,List<IndustrialConstructionSource> sources=null){lock(gate){if(World.ConstructionPolicyError(actor)!=null)throw new InvalidOperationException(World.ConstructionPolicyError(actor));var a=World.Actor(actor);if(a==null||count<0||count>0&&(!IndustrialCatalog.Items.ContainsKey(item??"")||(refund?!a.inventory.CanAdd(item,count):a.inventory.Count(item)<count)))throw new InvalidOperationException("Construction payment unavailable");var entry=new IndustrialJournalEntry{actor=actor,buildBody=body,buildJson=json,constructionActivity=activity,constructionSources=sources,typedConstruction=true,constructionItem=item,constructionCount=count,constructionRefund=refund,mounts=mounts,allocatedId=World.nextId};Append(entry);ApplyConstructionItem(World,entry);}}
        public void CommitConstructionResources(long actor,int body,string json,List<ItemStack> payment,bool refund,List<IndustrialMount> mounts,List<IndustrialConstructionSource> sources,List<IndustrialHaulObstacle> haulObstacles=null,List<IndustrialModulePorts> logisticsPorts=null){lock(gate){if(World.ConstructionPolicyError(actor)!=null)throw new InvalidOperationException(World.ConstructionPolicyError(actor));var owner=World.Actor(actor);if(owner==null||payment==null||refund&&!owner.inventory.CanAddBatch(payment)||!refund&&!owner.inventory.Has(payment.ToArray()))throw new InvalidOperationException("Construction resources unavailable");foreach(var item in payment)if(item.count<=0||!IndustrialCatalog.Items.ContainsKey(item.item))throw new InvalidOperationException("Invalid construction receipt");if(logisticsPorts!=null)foreach(var m in World.machines)if(m.integratedLogistics&&m.externalVehicle==0&&m.pose.body==body&&!logisticsPorts.Exists(p=>p.module==m.attachmentModule)&&(m.input.Used>0||World.belts.Exists(b=>b.source==m.id||b.target==m.id)))throw new InvalidOperationException("Empty module logistics and recover connected belts before removing it");var entry=new IndustrialJournalEntry{actor=actor,buildBody=body,buildJson=json,resourcePayment=true,constructionPayment=payment,constructionRefund=refund,mounts=mounts,constructionSources=sources,haulObstacles=haulObstacles,logisticsRules=logisticsPorts!=null,logisticsPorts=logisticsPorts,allocatedId=World.nextId};Append(entry);ApplyConstructionResources(World,entry);}}
        static void ApplyConstructionResources(IndustrialWorld world,IndustrialJournalEntry entry){if(entry.logisticsRules)world.SyncModulePorts(entry.buildBody,entry.logisticsPorts??new List<IndustrialModulePorts>());if(entry.haulObstacles!=null){world.haulObstacles.RemoveAll(x=>x.pose.body==entry.buildBody);world.haulObstacles.AddRange(entry.haulObstacles);}var owner=world.Actor(entry.actor);if(entry.constructionRefund)IndustrialConstruction.Return(owner.inventory,entry.constructionPayment);else foreach(var item in entry.constructionPayment)owner.inventory.Extract(item.item,item.count);var state=new IndustrialJournalEntry{actor=entry.actor,buildBody=entry.buildBody,buildJson=entry.buildJson,mounts=entry.mounts,constructionSources=entry.constructionSources};ApplyConstructionItem(world,state);}
        static void ApplyConstructionItem(IndustrialWorld world,IndustrialJournalEntry e){var a=world.Actor(e.actor);if(e.constructionCount>0){if(e.constructionRefund){if(!a.inventory.Add(e.constructionItem,e.constructionCount,e.constructionActivity))throw new InvalidDataException("Construction refund exceeds capacity");}else if(!a.inventory.Remove(e.constructionItem,e.constructionCount))throw new InvalidDataException("Construction journal overdraw");}if(e.constructionSources!=null){world.constructionSources.RemoveAll(x=>x.pose.body==e.buildBody);world.constructionSources.AddRange(e.constructionSources);}if(e.mounts!=null){world.mounts.RemoveAll(x=>x.pose.body==e.buildBody);world.mounts.AddRange(e.mounts);}ApplyConstruction(world,e.actor,e.buildBody,e.buildJson,0);}
        static void ApplyConstruction(IndustrialWorld world,long actor,int body,string json,int cost){var a=world.Actor(actor);if(cost>0){if(!a.inventory.Remove("stone",cost))throw new InvalidDataException("Construction journal overdraw");}else if(cost<0&&!a.inventory.Add("stone",-cost))throw new InvalidDataException("Construction refund exceeds capacity");var saved=world.buildStates.Find(x=>x.body==body);if(saved==null){saved=new ConstructionStorageRecord{body=body};world.buildStates.Add(saved);}saved.json=json;}
        public void MoveIndustrialVehicle(long actor,long vehicle,FramePose pose){lock(gate){var m=World.Machine(vehicle);if(m==null||m.haul?.active==true||m.owner!=actor||!IndustrialCatalog.Machines.ContainsKey(m.definition)||(m.definition!="truck"&&m.definition!="loader"&&m.definition!="excavator")||m.pose.Distance(pose)>3||double.IsNaN(pose.x)||double.IsNaN(pose.y)||double.IsNaN(pose.z)||double.IsInfinity(pose.x)||double.IsInfinity(pose.y)||double.IsInfinity(pose.z)||float.IsNaN(pose.yaw)||float.IsInfinity(pose.yaw))throw new InvalidOperationException("Invalid industrial vehicle movement");Append(new IndustrialJournalEntry{vehicleId=vehicle,vehiclePose=pose});m.pose=pose;}}
        // Terrain scale/height can change between saves; preserve finite deposit identity and stock.
        public int ReprojectSurfaceDeposits(int body,Func<FramePose,FramePose> project)=>RepositionSurfaceDeposits(body,deposit=>project(deposit.pose));
        public int RepositionSurfaceDeposits(int body,Func<SurfaceDeposit,FramePose> project,int layoutVersion=0){lock(gate){
            var changes=new List<IndustrialDepositProjection>();foreach(var deposit in World.deposits)if(deposit.pose.body==body&&deposit.pose.frame==0){var pose=project(deposit);if(pose.body!=body||pose.frame!=0||double.IsNaN(pose.x)||double.IsInfinity(pose.x)||double.IsNaN(pose.y)||double.IsInfinity(pose.y)||double.IsNaN(pose.z)||double.IsInfinity(pose.z))throw new ArgumentException("Invalid projected deposit position");if(pose.Distance(deposit.pose)>.25||layoutVersion>deposit.layoutVersion)changes.Add(new IndustrialDepositProjection{id=deposit.id,pose=pose,layoutVersion=Math.Max(layoutVersion,deposit.layoutVersion)});}
            if(changes.Count==0)return 0;Append(new IndustrialJournalEntry{depositProjections=changes});ApplyDepositProjections(World,changes);return changes.Count;
        }}
        static void ApplyDepositProjections(IndustrialWorld world,List<IndustrialDepositProjection> changes){foreach(var change in changes){var deposit=world.Deposit(change.id);if(deposit==null)throw new InvalidDataException("Missing projected deposit");deposit.pose=change.pose;deposit.layoutVersion=change.layoutVersion;}}
        public void EnableMiningWorkflow(){lock(gate){if(World.miningWorkflow)return;if(path!=null&&!File.Exists(path))Save();Append(new IndustrialJournalEntry{miningWorkflowEnabled=true});World.EnableMiningWorkflow();}}
        public string CreateTailingsDump(long sluice,FramePose pose){lock(gate){var machine=World.Machine(sluice);if(machine?.tailingsDump>0&&World.Pile(machine.tailingsDump)!=null)return null;string error=World.WasteSiteError(sluice,pose);if(error!=null)return error;var site=new IndustrialWasteSite{sluice=sluice,pile=World.nextId,pose=pose};Append(new IndustrialJournalEntry{wasteSite=site});World.ApplyWasteSite(site);return null;}}
        public string ReplanTruck(IndustrialHaulReplan request){lock(gate){string error=World.PrepareHaulReplan(request,out var apply);if(error!=null)return error;Append(new IndustrialJournalEntry{haulReplan=request});apply();return null;}}
        public void Step(int count=1){if(count<1||count>1000)throw new ArgumentOutOfRangeException(nameof(count));lock(gate){var poses=new List<IndustrialActorCheckpoint>();foreach(var actor in World.actors)poses.Add(new IndustrialActorCheckpoint{id=actor.id,pose=actor.pose,health=actor.health,collisionRadius=actor.collisionRadius,vehicleObstacle=actor.vehicleObstacle,vehicleObstacleRadius=actor.vehicleObstacleRadius});var environments=new List<IndustrialPowerEnvironment>();foreach(var e in World.powerEnvironments)environments.Add(new IndustrialPowerEnvironment{body=e.body,sunX=e.sunX,sunY=e.sunY,sunZ=e.sunZ,wind=e.wind});Append(new IndustrialJournalEntry{steps=count,actors=poses,powerEnvironments=environments,dropPositions=World.CaptureDropPositions(),survival=World.multiplayer});for(int n=0;n<count;n++)World.Step();}}
        static void ReplaceCheckpoint(string temp,string destination){
            for(int attempt=0;;attempt++)try{File.Replace(temp,destination,destination+".bak");return;}
            catch(IOException error)when(attempt<3&&File.Exists(temp)&&((error.HResult&65535)==32||(error.HResult&65535)==33||(error.HResult&65535)==1175)){
                // Windows scanners/readers can briefly hold the old backup. Keep atomic replacement.
                System.Threading.Thread.Sleep(10<<attempt);
            }
        }
        public void Save(){if(path==null||disposed)return;lock(gate){long started=CheckpointTiming==null?0:System.Diagnostics.Stopwatch.GetTimestamp();string temp=path+".tmp";using(var f=new FileStream(temp,FileMode.Create,FileAccess.Write,FileShare.None)){worldSerializer.Serialize(f,World);f.Flush(true);}if(File.Exists(path))ReplaceCheckpoint(temp,path);else File.Move(temp,path);
                // Snapshot is durable before journal compaction; replay skips records already in the snapshot.
                writer.Flush();journal.SetLength(0);journal.Position=0;journal.Flush(true);
                if(CheckpointTiming!=null)try{CheckpointTiming(PersistenceMilliseconds(started));}catch(Exception){/* Diagnostics do not change checkpoint durability. */}
            }}
        public static IndustrialWorld Load(string path){
            IndustrialWorld world=null;if(File.Exists(path)){using(var f=File.OpenRead(path))world=(IndustrialWorld)worldSerializer.Deserialize(f);}
            if(world==null){if(File.Exists(path+".journal")&&new FileInfo(path+".journal").Length>0)throw new InvalidDataException("Journal exists without its initial snapshot");return new IndustrialWorld();}if(world.version!=IndustrialWorld.Version)throw new InvalidDataException("Unsupported industrial save version");world.MigrateCraftIds();
            if(File.Exists(path+".journal")){
                // A crash can leave the final line incomplete. Earlier corruption is an error, never skipped.
                string journalText=File.ReadAllText(path+".journal");int complete=journalText.LastIndexOf('\n');if(complete<journalText.Length-1){using(var tail=new FileStream(path+".journal",FileMode.Open,FileAccess.Write,FileShare.Read)){tail.SetLength(Encoding.UTF8.GetByteCount(complete<0?"":journalText.Substring(0,complete+1)));tail.Flush(true);}journalText=complete<0?"":journalText.Substring(0,complete+1);}string[] lines=journalText.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries);for(int i=0;i<lines.Length;i++){
                    IndustrialJournalEntry e;try{using(var text=new StringReader(Encoding.UTF8.GetString(Convert.FromBase64String(lines[i]))))e=(IndustrialJournalEntry)entrySerializer.Deserialize(text);}catch(Exception error)when(error is FormatException||error is InvalidOperationException){throw new InvalidDataException("Corrupt industrial journal",error);}
                    if(e.serial<=world.journalSequence)continue;if(e.serial!=world.journalSequence+1)throw new InvalidDataException("Industrial journal has a sequence gap");
                    if(e.universe!=null){if(world.universe!=null)throw new InvalidDataException("Duplicate universe initialization");world.universe=e.universe;}
                    else if(e.registration!=null)ApplySurvivorRegistration(world,e.registration);
                    else if(e.survivalCheckpoint){world.multiplayer=e.survival;world.RestoreNetworkVehiclePoses();foreach(var state in e.actors){var who=world.Actor(state.id)??throw new InvalidDataException("Missing survivor");who.pose=state.pose;who.health=state.health;}}
                    else if(e.weaponAttack!=null)ApplySurvivalWeapon(world,e.weaponAttack);
                    else if(e.playerCombat!=null)ApplyPlayerCombat(world,e.playerCombat);
                    else if(e.inventory!=null)world.ApplyInventory(e.inventory);
                    else if(e.respawn!=null)world.ApplyRespawn(e.respawn);
                    else if(e.miningWorkflowEnabled)world.EnableMiningWorkflow();
                    else if(e.wasteSite!=null)world.ApplyWasteSite(e.wasteSite);
                    else if(e.depositProjections!=null&&e.depositProjections.Count>0)ApplyDepositProjections(world,e.depositProjections);
                    else if(e.steps>0){if(e.survival!=null){world.multiplayer=e.survival;world.RestoreNetworkVehiclePoses();}if(e.dropPositions!=null)foreach(var point in e.dropPositions){var drop=world.Dropped(point.id);if(drop!=null)drop.resolvedPose=point.pose;}if(e.powerEnvironments!=null)foreach(var environment in e.powerEnvironments)world.SetPowerEnvironment(environment.body,environment.sunX,environment.sunY,environment.sunZ,environment.wind);if(e.actors!=null)foreach(var state in e.actors){var who=world.Actor(state.id);if(who==null)throw new InvalidDataException("Missing actor checkpoint");who.pose=state.pose;who.health=state.health;who.collisionRadius=state.collisionRadius;who.vehicleObstacle=state.vehicleObstacle;who.vehicleObstacleRadius=state.vehicleObstacleRadius;}if(e.steps>1000)throw new InvalidDataException("Invalid tick batch");for(int t=0;t<e.steps;t++)world.Step();}
                    else if(e.haulReplan!=null){string error=world.PrepareHaulReplan(e.haulReplan,out var apply);if(error!=null)throw new InvalidDataException("Haul replan rejected: "+error);apply();}
                    else if(e.vehicleId!=0){var vehicle=world.Machine(e.vehicleId);if(vehicle==null)throw new InvalidDataException("Missing journal vehicle");vehicle.pose=e.vehiclePose;}
                    else if(e.buildJson!=null){if(e.resourcePayment)ApplyConstructionResources(world,e);else if(e.typedConstruction)ApplyConstructionItem(world,e);else ApplyConstruction(world,e.actor,e.buildBody,e.buildJson,e.stoneCost);}
                    else {var a=world.Actor(e.actor);if(a==null)throw new InvalidDataException("Missing journal actor");a.pose=e.actorPose;if(!e.kitRules&&e.command.kind=="place")ApplyLegacyPlacement(world,a,e.command);else {var result=world.Execute(e.actor,e.command,null,!e.resourceRules);if(!result.accepted)throw new InvalidDataException("Journal replay rejected: "+result.message);}}
                    if(e.networkSequence>0){var player=world.multiplayer?.players.Find(p=>p.actor==e.networkActor);if(player==null)throw new InvalidDataException("Missing network identity");player.lastActionSequence=Math.Max(player.lastActionSequence,e.networkSequence);}
                    world.nextId=Math.Max(world.nextId,e.allocatedId);world.journalSequence=e.serial;
                }
            }return world;
        }
        // Old durable journals paid raw ingredients. Replay those accepted records without
        // changing their price or making the compatibility path a network command.
        static void ApplyLegacyPlacement(IndustrialWorld world,IndustrialActor actor,IndustrialCommand command){var definition=IndustrialCatalog.Machines[command.definition];var cost=definition.Vehicle?IndustrialCatalog.LegacyMachineCost(definition.id):IndustrialCatalog.Recipes[definition.id+"-kit"].input;if(!actor.inventory.Has(cost))throw new InvalidDataException("Legacy construction journal overdraw");double activity=0;foreach(var input in cost)activity+=actor.inventory.Extract(input.item,input.count);world.machines.Add(new IndustrialMachine{id=world.AllocateId(),owner=actor.id,pose=command.pose,definition=definition.id,recipe=definition.recipe,input=new Inventory{capacity=definition.capacity},output=new Inventory{capacity=definition.capacity},constructionActivity=activity});actor.lastSequence=command.sequence;actor.lastCommand=command.Fingerprint();}
        public static string Snapshot(IndustrialWorld world){using(var text=new StringWriter(System.Globalization.CultureInfo.InvariantCulture)){worldSerializer.Serialize(text,world);return text.ToString();}}
        public static IndustrialWorld Restore(string data){using(var text=new StringReader(data)){var world=(IndustrialWorld)worldSerializer.Deserialize(text);world.MigrateCraftIds();return world;}}
        public void Dispose(){if(disposed)return;disposed=true;writer?.Dispose();journal?.Dispose();}
    }
